def seed_database():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        if db.query(Product).count() > 0:
            return
        categories = {}
        for name, desc, icon in CATEGORY_DATA:
            c = Category(name=name, description=desc, icon=icon)
            db.add(c)
            db.flush()
            categories[name] = c.id
        for p in PRODUCT_DATA:
            db.add(Product(
                sku=p["sku"], name=p["name"], category_id=categories[p["category"]],
                price=p["price"], old_price=p["old_price"], rating=p["rating"],
                reviews=p["reviews"], image=p["image"], badge=p["badge"],
                description=p["description"], stock=p["stock"]
            ))
        db.commit()
    finally:
        db.close()
